"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["98366"],{28816(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.regra_de_deliberacao_obrigatoria","status":422,"titulo":"Toda banca declara a regra de delibera\xe7\xe3o para o processo ser publicado"},"descricao":{"codigo":"uniplus.selecao.banca.regra_de_deliberacao_obrigatoria","requisitos":["UNI-REQ-0275"],"oQueAconteceu":["A banca foi declarada na fase ou na etapa sem a regra de delibera\xe7\xe3o, e o edital\\nn\xe3o pode ser publicado assim. No rascunho a regra \xe9 opcional, para que a banca\\npossa ser declarada aos poucos; a publica\xe7\xe3o a exige, porque o sistema n\xe3o imp\xf5e\\nnenhuma regra de decis\xe3o \xe0 banca: quem a define \xe9 o edital (UNI-REQ-0275). Sem\\nela, no julgamento n\xe3o haveria como saber quantos votos decidem, como se\\ndesempata nem quando a vota\xe7\xe3o termina.","A mesma confer\xeancia roda na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico. A recusa\\nvem como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na lista `errors[]`: a publica\xe7\xe3o aponta uma pend\xeancia por vez, a primeira que\\nencontra."],"comoResolver":["Informe a regra de delibera\xe7\xe3o da banca, do modo que o edital declara:","- **`colegiadaComVotacao`:** n\xfamero de integrantes e de suplentes, qu\xf3rum,\\n  crit\xe9rio de decis\xe3o e forma de encerramento, al\xe9m do desempate e do valor para\\n  a unanimidade n\xe3o alcan\xe7ada, nos casos em que se aplicam.\\n- **`atoIndividual`:** sem qu\xf3rum nem vota\xe7\xe3o, como na banca de homologa\xe7\xe3o das\\n  inscri\xe7\xf5es (UNI-REQ-0338).","Os campos da regra s\xe3o conferidos j\xe1 na grava\xe7\xe3o do cronograma e das etapas,\\ncada um com a sua recusa, antes da publica\xe7\xe3o. O painel de conformidade aponta a\\nbanca sem regra, no item `cronograma_banca_com_regra_de_deliberacao`."],"ondeAparece":["Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);